<?php
// Customer order history and status filters.

    $status=input('status',input('status1')); $params=[$userId]; $where='';
    if ($status === '__received') $where=" AND o.status IN ('Selesai','Selesai Belum Dinilai')";
    elseif ($status === '__rating') $where=" AND o.status IN ('Dikirim','Selesai Belum Dinilai') AND EXISTS (SELECT 1 FROM details rd WHERE rd.id_orders=o.id_orders AND rd.rating=0)";
    elseif ($status) { $where=' AND o.status=?'; $params[]=$status; }
    $orders=query('SELECT o.*, j.nama_jasa,j.harga_jasa,m.nama_metode,m.harga_admin FROM orders o JOIN jasa_kirim j ON j.id_jasa=o.id_jasa JOIN metode m ON m.id_metode=o.id_metode WHERE o.id_user=?'.$where.' ORDER BY o.id_orders DESC',$params);
    $statusCounts = query("SELECT status, COUNT(*) AS total FROM orders WHERE id_user=? GROUP BY status", [$userId]);
    $counts = []; foreach ($statusCounts as $statusCount) $counts[$statusCount['status']] = (int)$statusCount['total'];
    $toReview = (int)(one("SELECT COUNT(DISTINCT o.id_orders) AS n FROM orders o JOIN details d ON d.id_orders=o.id_orders WHERE o.id_user=? AND o.status IN ('Dikirim','Selesai Belum Dinilai') AND d.rating=0", [$userId])['n'] ?? 0);
    $receivedCount = ($counts['Selesai'] ?? 0) + ($counts['Selesai Belum Dinilai'] ?? 0);
    page_title('MY ORDERS','Setiap pesanan, dalam pantauan.','Lihat pembayaran, pengiriman, dan riwayat belanja Anda.'); ?>
    <section class="order-overview" aria-label="Ringkasan status pesanan"><?php foreach ([['Belum Bayar','Menunggu pembayaran','bag','Belum Bayar'],['Diproses','Sedang disiapkan','box','Diproses'],['Dikirim','Paket sedang dikirim','truck','Dikirim'],['Diterima','Paket sudah diterima','check','__received']] as [$statusName,$description,$glyph,$filter]): $summaryCount=$statusName==='Diterima'?$receivedCount:($counts[$statusName]??0); ?><a href="<?= e(url('pages/pesanan.php?status=' . rawurlencode($filter))) ?>"><span><?= icon($glyph) ?></span><span><strong><?= (int)$summaryCount ?></strong><small><?= e($description) ?></small></span></a><?php endforeach; ?></section>
    <?php if ($toReview): ?><a class="review-reminder" href="<?= e(url('pages/pesanan.php?status=__rating')) ?>"><span class="reminder-icon"><?= icon('check') ?></span><span><strong>Paket sudah diterima?</strong><small><?= $toReview ?> pesanan menunggu konfirmasi penerimaan dan ulasan Anda. Beri rating untuk membantu pembeli lain.</small></span><span class="reminder-action">Konfirmasi & beri ulasan <?= icon('arrow') ?></span></a><?php endif; ?>
    <?php $filterTabs=[''=>'Semua','Belum Bayar'=>'Belum bayar','Menunggu Konfirmasi'=>'Menunggu konfirmasi','Diproses'=>'Diproses','Dikirim'=>'Dikirim','__received'=>'Diterima','Dibatalkan'=>'Dibatalkan','__rating'=>'Penilaian']; ?>
    <nav class="tabs order-tabs" aria-label="Filter pesanan"><?php foreach($filterTabs as $v=>$label): $tabCount=$v==='__rating'?$toReview:($v==='__received'?$receivedCount:($v===''?0:($counts[$v]??0))); ?><a class="<?= $status===$v?'active':'' ?>" href="<?= e(url('pages/pesanan.php?' . http_build_query(['status'=>$v]))) ?>"><?= e($label) ?><?php if($tabCount>0): ?><span class="order-tab-count" aria-label="<?= (int)$tabCount ?> pesanan"><?= (int)$tabCount ?></span><?php endif; ?></a><?php endforeach; ?></nav>
    <?php if (!$orders) empty_state('Belum ada pesanan','Pesanan Anda akan muncul di sini setelah checkout.'); foreach($orders as $ord): $details=order_details($ord['id_orders']); ?><article class="panel order-card"><div class="order-heading"><div><strong>#TM-<?= (int)$ord['id_orders'] ?></strong><span class="muted"> · <?= e(date('d M Y',strtotime($ord['tanggal']))) ?> · <?= e($ord['nama_jasa']) ?></span></div><?= status_badge($ord['status']) ?></div><?php foreach($details as $item): ?><div class="mini-product"><img src="<?= e(url($item['img'])) ?>" alt=""><div><strong><?= e($item['nama_barang']) ?></strong><small><?= (int)$item['qty'] ?> × <?= rupiah($item['harga_satuan']) ?></small></div><strong class="line-total"><?= rupiah($item['harga_satuan']*$item['qty']) ?></strong></div><?php endforeach; ?><?php if($ord['status']==='Belum Bayar'): $orderSubtotal=array_sum(array_map(function($d){return $d['harga_satuan']*$d['qty'];},$details)); ?><div class="unpaid-breakdown"><div><h3>Rincian pembayaran</h3><p class="muted small-text">Pesanan sudah dibuat. Lanjutkan pembayaran agar dapat diproses.</p></div><div><div class="summary-line"><span>Subtotal produk (<?= array_sum(array_column($details,'qty')) ?> unit)</span><strong><?= rupiah($orderSubtotal) ?></strong></div><div class="summary-line"><span><?= e($ord['nama_jasa']) ?></span><strong><?= rupiah($ord['harga_jasa']) ?></strong></div><div class="summary-line"><span><?= e($ord['nama_metode']) ?> &middot; biaya pembayaran</span><strong><?= rupiah($ord['harga_admin']) ?></strong></div><div class="summary-line total"><span>Total pembayaran</span><strong><?= rupiah($orderSubtotal+$ord['harga_jasa']+$ord['harga_admin']) ?></strong></div></div></div><?php endif; ?><div class="order-actions"><a class="button small secondary" href="<?= e(url('pages/pembayaran.php?id='.$ord['id_orders'])) ?>"><?= $ord['status']==='Belum Bayar'?'Bayar sekarang':'Detail pembayaran' ?></a><?php if($ord['status']==='Belum Bayar') action_form('cancel',$ord['id_orders'],'Batalkan','button small ghost','Batalkan pesanan ini?'); if(in_array($ord['status'],['Dikirim','Selesai Belum Dinilai'])): ?><a class="button small" href="<?= e(url('pages/rating.php?id='.$ord['id_orders'])) ?>">Terima & beri ulasan</a><?php endif; if(in_array($ord['status'],['Dikirim','Selesai','Selesai Belum Dinilai']) && !one('SELECT id_refund FROM tb_refund WHERE id_orders=?',[(int)$ord['id_orders']])): ?><a class="text-link" href="<?= e(url('pages/refund.php?id='.$ord['id_orders'])) ?>">Ajukan retur</a><?php endif; $refund=one('SELECT status_refund FROM tb_refund WHERE id_orders=? ORDER BY id_refund DESC LIMIT 1',[(int)$ord['id_orders']]); if($refund) echo '<span>Retur: '.status_badge($refund['status_refund']).'</span>'; ?></div></article><?php endforeach;
